steps.run:
set -euo pipefail
case "${{ matrix.validator }}" in
  build-index-v1)
    python3 scripts/build_lattice_global_index.py --repo-root . | tee build-index-v1.report.json
    ;;
  build-index-v2)
    python3 scripts/build_lattice_global_index_v2.py --repo-root . | tee build-index-v2.report.json
    ;;
  broken-links)
    python3 scripts/validate_markdown_links.py --repo-root . | tee broken-links.report.json
    ;;
  edge-directions)
    python3 scripts/validate_edge_directions.py --repo-root . | tee edge-directions.report.json
    ;;
  supersedes-chain)
    python3 scripts/validate_supersedes_chain.py --repo-root . | tee supersedes-chain.report.json
    ;;
  governance-self-promotion)
    python3 scripts/validate_no_self_promotion.py --repo-root . | tee governance-self-promotion.report.json
    ;;
  governance-trust-state)
    python3 scripts/validate_trust_state.py --repo-root . | tee governance-trust-state.report.json
    ;;
  governance-deployment-state)
    python3 scripts/validate_deployment_state.py --repo-root . | tee governance-deployment-state.report.json
    ;;
  supply-chain)
    python3 scripts/validate_supply_chain_workflow.py | tee supply-chain.report.json
    ;;
  pytest)
    python3 -m pytest -q tests/ | tee pytest.report.txt
    ;;
esac

